import 'package:flutter/widgets.dart';

/// Lightweight in-app localization (no codegen). Mirrors the 6 languages the
/// user app ships with. Only the auth/onboarding flow is fully translated;
/// the dashboard falls back to English where a translation is absent.
///
/// `S.of(context)` returns the active [Strings] for the current locale.
class Strings {
  final String code;
  const Strings(this.code);

  static const supportedLocales = <Locale>[
    Locale('en'),
    Locale('hi'),
    Locale('bn'),
    Locale('mr'),
    Locale('pa'),
    Locale('as'),
    Locale('kn'),
    Locale('te'),
    Locale('ta'),
  ];

  static const languageNames = <String, String>{
    'en': 'English',
    'hi': 'हिन्दी',
    'bn': 'বাংলা',
    'mr': 'मराठी',
    'pa': 'ਪੰਜਾਬੀ',
    'as': 'অসমীয়া',
    'kn': 'ಕನ್ನಡ',
    'te': 'తెలుగు',
    'ta': 'தமிழ்',
  };

  static Strings of(BuildContext context) {
    final code = Localizations.localeOf(context).languageCode;
    return Strings(_table.containsKey(code) ? code : 'en');
  }

  /// Tenant brand name, substituted into any `{appName}` placeholder in a string.
  /// Set once at startup from the tenant config (GET /app-config → appName).
  /// Neutral default so a build with no config never shows another tenant's name.
  static String brandName = 'Astro App';

  /// Tenant's uploaded logo URL (GET /app-config → logoUrl). Empty when unset —
  /// RgLogo then falls back to the brand initials. Set once at startup.
  static String brandLogoUrl = '';

  /// Look up a translated string and substitute the tenant brand into the
  /// `{appName}` placeholder, so localized text shows THIS tenant's name (never
  /// a hardcoded brand). Falls back to English, then the raw key.
  String _t(String key) {
    final raw = _table[code]?[key] ?? _table['en']![key] ?? key;
    return raw.contains('{appName}') ? raw.replaceAll('{appName}', brandName) : raw;
  }

